#!/usr/bin/env python3
"""Minimal page generator for stations-electriques-portables."""
import os, json
BASE = os.path.dirname(os.path.abspath(__file__))

def cp(c):
    # The site uses its own domain, so the root-relative path works from every page.
    return "/style.css"
def write(path, html):
    f=os.path.join(BASE,path.lstrip("/")); os.makedirs(os.path.dirname(f),exist_ok=True)
    open(f,"w",encoding="utf-8").write(html); print(f"  ✓ {path}")
def bc_html(*items):
    p=['<a href="/">Accueil</a><span class="sep">/</span>']
    for i,x in enumerate(items):
        p.append(f'<a href="{x[1]}">{x[0]}</a>' if isinstance(x,tuple) and len(x)>1 else f'<span>{x[0] if isinstance(x,tuple) else x}</span>')
        if i<len(items)-1: p.append('<span class="sep">/</span>')
    return ''.join(p)
def stars(n): return f'<span class="star-full">{"★"*n}</span><span class="star-empty">{"☆"*(3-n)}</span>'
def rel_html(items): return ''.join('<a href="'+u+'">'+l+'</a>' for l,u in (i for i in items if len(i)==2))
def aut_rows(wh):
    r=""
    for nm,w in [("PC portable",60),("TV 40\"",100),("Glacière 12V",45),("Réfrigérateur",120),("Machine à café",1200),("Lampe LED",10),("CPAP",30)]:
        h=wh*0.85/w; v=f"{h*60:.0f} min cumulées" if w>=1000 else (f"{h:.1f} h" if h>=1 else f"{h*60:.0f} min")
        r+=f'<tr><td>{nm}</td><td class="col-w">{w} W</td><td class="col-aut">{v}</td></tr>'
    return r

