def doc(title, desc, canonical, body):
    return f'<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>{title}</title><meta name="description" content="{desc}"><meta name="robots" content="noindex, follow"><link rel="canonical" href="https://stations-electriques-portables.fr{canonical}"><link rel="stylesheet" href="{cp(canonical)}"><link rel="preconnect" href="https://fonts.googleapis.com"></head><body>{HDR}<main>{body}</main>{FTR}</body></html>'

def hub(title,desc,canonical,bc_items,intro,links):
    items="".join(f'<a href="{u}" class="hub-link"><div><div>{l}</div><div class="hub-link-meta">{m}</div></div><span>→</span></a>' for l,u,m in links)
    body=f'<div class="container"><nav class="breadcrumb">{bc_html(*bc_items)}</nav></div><section class="page-hero"><div class="container"><h1>{title}</h1><p class="lead">{intro}</p></div></section><section class="section"><div class="container"><div class="hub-grid">{items}</div></div></section>'
    return doc(title,desc,canonical,body)

def page(title,desc,canonical,bc_items,ctype="guide",answer="",related=None):
    ans=f'<div class="answer-box"><p>{answer}</p></div>' if answer else ""
    rel=f'<div class="related-box"><h4>À lire aussi</h4><div class="related-links">{rel_html(related or [])}</div></div>' if related else ""
    body=f'<div class="container"><nav class="breadcrumb">{bc_html(*bc_items)}</nav></div><section class="page-hero"><div class="container"><span class="ctype ctype-{ctype}">{ctype.title()}</span><h1 style="margin-top:10px">{title}</h1><p class="lead">{desc}</p><div class="page-meta"><span class="meta-tag">Vérifié : MM/AAAA</span></div></div></section><div class="container"><div class="content-layout"><article class="content-main">{ans}<!-- Contenu à rédiger -->{rel}</article><aside class="content-sidebar"><div class="sidebar-box"><div class="sidebar-box-head">Sommaire</div><div class="sidebar-box-body"><nav class="toc-list"></nav></div></div><div class="sidebar-box"><div class="sidebar-box-head">Affiliation</div><div class="sidebar-box-body"><p class="affil-note">Liens affiliés présents. <a href="/transparence-affiliation/">En savoir plus.</a></p></div></div><a href="/calculateur-autonomie/" class="btn btn-primary" style="width:100%;justify-content:center">⚡ Calculateur</a></aside></div></div>'
    return doc(title,desc,canonical,body)

def modele_page(m):
    wh,w,peak,chem=m["wh"],m["w"],m["peak"],m["chem"]
    cb="lifepo4" if "LiFePO4" in chem else "liion"
    sr=f'<tr><td class="sk">Marque</td><td class="sv">{m["brand"]}</td></tr><tr><td class="sk">Capacité</td><td class="sv">{wh} Wh</td></tr><tr><td class="sk">Puissance continue</td><td class="sv">{w} W</td></tr><tr><td class="sk">Puissance crête</td><td class="sv">{peak} W</td></tr><tr><td class="sk">Batterie</td><td class="sv">{chem}</td></tr><tr><td class="sk">Cycles</td><td class="sv">≈ {m["cycles"]:,}</td></tr><tr><td class="sk">Entrée solaire max.</td><td class="sv">{m["solar"]} W</td></tr><tr><td class="sk">UPS</td><td class="sv">{"Oui" if m.get("ups") else "Non"}</td></tr><tr><td class="sk">Poids</td><td class="sv">{m["kg"]} kg</td></tr><tr><td class="sk">Données vérifiées</td><td class="sv">MM/AAAA</td></tr>'
    pros="".join(f"<li>{p}</li>" for p in m.get("pros",[]))
    cons="".join(f"<li>{c}</li>" for c in m.get("cons",[]))
    rat=m.get("rat",{}); uc="".join(f'<div class="usage-score-card"><div class="usc-name">{lb}</div><div class="usc-stars">{stars(rat.get(k,1))}</div></div>' for k,lb in [("cam","Camping"),("van","Van"),("mai","Maison"),("tel","Télétravail"),("cha","Chantier"),("ran","Randonnée")])
    rel=m.get("rel",[]); rh=f'<div class="related-box"><h4>À lire aussi</h4><div class="related-links">{rel_html(rel)}</div></div>' if rel else ""
    body=f'<div class="container"><nav class="breadcrumb">{bc_html(("Modèles","/modeles/"),m["name"])}</nav></div><section class="page-hero"><div class="container"><div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px"><span class="badge badge-{cb}">{chem}</span><span class="badge badge-dark">{m["brand"]}</span><span class="ctype ctype-modele">Fiche modèle</span></div><h1 style="margin-bottom:8px">{m["name"]}</h1><p class="lead">{m.get("desc","")}</p><div class="model-kpi-row" style="margin-top:24px"><div class="kpi-box"><div class="kpi-val">{wh}<em> Wh</em></div><div class="kpi-label">Capacité</div></div><div class="kpi-box"><div class="kpi-val">{w}<em> W</em></div><div class="kpi-label">Puissance</div></div><div class="kpi-box"><div class="kpi-val">{chem.split()[0]}</div><div class="kpi-label">Batterie</div></div><div class="kpi-box"><div class="kpi-val">≈{m["cycles"]:,}</div><div class="kpi-label">Cycles</div></div></div></div></section><div class="container"><div class="content-layout"><article class="content-main"><div class="pro-con-grid"><div class="pro-box"><h4>Idéal pour</h4><ul>{pros}</ul></div><div class="con-box"><h4>À considérer</h4><ul>{cons}</ul></div></div><h2>Pour quels usages ?</h2><div class="usage-matrix">{uc}</div><h2>Que peut-elle alimenter ?</h2><p>Avec <strong>{wh} Wh</strong> ({int(wh*0.85)} Wh utiles estimés) :</p><div class="power-table-wrap"><table class="power-table"><thead><tr><th>Appareil</th><th>Conso.</th><th>Autonomie estimée</th></tr></thead><tbody>{aut_rows(wh)}</tbody></table><div class="power-note">Estimations indicatives.</div></div>{rh}</article><aside class="content-sidebar"><div class="spec-sheet"><div class="spec-sheet-header"><span>Fiche technique</span><span class="verified">✓ Vérifiées</span></div><table class="spec-table">{sr}</table></div><a href="#prix" class="btn btn-primary" style="width:100%;justify-content:center">Voir les offres</a><a href="/calculateur-autonomie/" class="btn btn-ghost" style="width:100%;justify-content:center">⚡ Calculateur</a></aside></div></div>'
    return doc(f'{m["name"]} — Fiche technique et autonomie',m.get("desc",""),m["path"],body)

