calc_body=f'<div class="container"><nav class="breadcrumb">{_bc_calc}</nav></div><section class="page-hero"><div class="container"><h1>Calculateur d\'autonomie</h1><p class="lead">Entrez la puissance de votre appareil et la durée souhaitée.</p></div></section><section class="section"><div class="container" style="max-width:720px"><div class="calculator"><div class="calc-header"><div class="calc-eyebrow">Outil de dimensionnement</div><h2>Calculateur d\'autonomie</h2></div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px"><button class="pb" data-p="60" data-d="8" style="padding:6px 12px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.15);border-radius:4px;color:rgba(255,255,255,.7);font-size:.75rem;cursor:pointer">PC·8h</button><button class="pb" data-p="120" data-d="12" style="padding:6px 12px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.15);border-radius:4px;color:rgba(255,255,255,.7);font-size:.75rem;cursor:pointer">Frigo·12h</button><button class="pb" data-p="45" data-d="24" style="padding:6px 12px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.15);border-radius:4px;color:rgba(255,255,255,.7);font-size:.75rem;cursor:pointer">Glacière·24h</button><button class="pb" data-p="30" data-d="8" style="padding:6px 12px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.15);border-radius:4px;color:rgba(255,255,255,.7);font-size:.75rem;cursor:pointer">CPAP·8h</button></div><div class="calc-inputs"><div class="calc-field"><label>Puissance (W)</label><input type="number" id="cpi" placeholder="ex. 100" min="1"></div><div class="calc-field"><label>Durée (heures)</label><input type="number" id="cdi" placeholder="ex. 8" min="0.5" step="0.5"></div></div><button class="calc-btn" id="cbt">Calculer →</button><div class="calc-result" id="crs"><div class="calc-result-grid"><div class="calc-result-box"><div class="crb-val" id="rn">—</div><div class="crb-label">Besoin théorique</div></div><div class="calc-result-box highlight"><div class="crb-val" id="rr">—</div><div class="crb-label">Recommandé (+15%)</div></div></div><div class="calc-matches-title">Stations correspondantes</div><div id="cm"></div><div id="cnr" style="display:none;color:rgba(255,255,255,.4);font-size:.85rem;padding:16px;text-align:center">Aucune station ne correspond.</div></div></div><div class="related-box" style="margin-top:24px"><h4>En savoir plus</h4><div class="related-links"><a href="/guides/watt-ou-watt-heure/">W vs Wh</a><a href="/guides/calculer-autonomie-station-electrique/">Guide : calculer son autonomie</a></div></div></div></section><script>const S={SJ};function fw(w){{return w>=1000?(w/1000).toFixed(1).replace(\'.0\',\'\')+\' kWh\':Math.round(w)+\' Wh\';}}function go(){{const p=parseFloat(document.getElementById(\'cpi\').value)||0,d=parseFloat(document.getElementById(\'cdi\').value)||0;if(!p||!d)return;const n=p*d,r=Math.ceil(n/0.85);document.getElementById(\'rn\').textContent=fw(n);document.getElementById(\'rr\').textContent=fw(r);const m=S.filter(s=>s.wh>=r&&s.w>=p).sort((a,b)=>a.wh-b.wh).slice(0,5);document.getElementById(\'cnr\').style.display=m.length?\'none\':\'block\';document.getElementById(\'cm\').innerHTML=m.map(s=>`<a href="${{s.url}}" class="calc-match-row"><span class="cmr-name">${{s.name}}</span><span class="cmr-specs">${{s.wh}} Wh·${{s.w}} W →</span></a>`).join(\'\');document.getElementById(\'crs\').classList.add(\'active\');}}document.getElementById(\'cbt\').addEventListener(\'click\',go);document.querySelectorAll(\'.pb\').forEach(b=>b.addEventListener(\'click\',function(){{if(this.dataset.p)document.getElementById(\'cpi\').value=this.dataset.p;if(this.dataset.d)document.getElementById(\'cdi\').value=this.dataset.d;go();}}));</script>'
write("/calculateur-autonomie/index.html",doc("Calculateur d'autonomie — Station électrique portable","Calculez la capacité nécessaire selon votre appareil et durée.","/calculateur-autonomie/",calc_body))

